def divisor_count(n):
    if n < 2:
        return 1
    if n % 2 == 1:
        return 0
    count = 0
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            count += 2
            if i * i != n:
                count += divisor_count(n // i)
    return count

    def ways_to_divide(n):
        if n == 0:
            return 1
        if n == 1:
            return 1
        if n == 2:
            return 2
        count = 0
        for i in range(1, n + 1):
            if divisor_count(i) == divisor_count(n - i):
                count += 1
        return count

    n = val()
    print(ways_to_divide(n))

