from math import factorial

def stirling2(n, k):
    if n < k or k <= 0:
        return 0
    if n == k or k == 1:
        return 1
    result = 0
    for i in range(1, min(n, k)):
        result += stirling2(n - i, k - 1) * factorial(n - 1)
    return result

# Test the Stirling numbers of the second kind
print(stirling2(5, 3))```

