from math import pi, sin
import numpy as np

def taylor_sin(x, n):
    terms = np.power(-1, np.arange(n))
    return sum(terms * (x**(2*i+1)) / np.factorial(2*i+1) for i in range(n))

def sin_approx(x, n):
    return taylor_sin(x, n) + sin(x) * (1 - taylor_sin(x, n)**2) / 6
