def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def count_primes(n):
    primes = [2] 
    sieve = [True] * (n + 1)
    for p in primes:
        for i in range(p*p, n + 1, p):
            sieve[i] = False
    count = sum(sieve)
    return count

def main():
    n = 10
    print(count_primes(n))

if __name__ == '__main__':
    main()```

