import math
def smallest_prime(n):
	if n <= 1:
		return 2
	is_prime = [True] * (n + 1)
	is_prime[0] = False
	is_prime[1] = False

	for i in range(2, int(math.sqrt(n)) + 1):
		if is_prime[i]:
			for j in range(i * i, n + 1, i):
				is_prime[j] = False
	for i in range(n + 1, len(is_prime)):
		if is_prime[i]:
			return i

