def distinct_powers_of_two(n: int) -> int:
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for k in range(1, i):
            if i - (1 << k) >= 0 and dp[i - (1 << k)]:
                dp[i] += dp[i - (1 << k)]
    return dp[n] - 1
```

