def num_ways(n, d): 
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1): 
        for j in range(1, i): 
            if (i - j) <= d or (i - j) <= d + 1: 
                dp[i] += dp[j]
    return dp[n]

def __starting_point(): 
    n = 10
    d = 3
    print(num_ways(n, d))
__starting_point()
